import copy


def _parse_path(path):
    """Parse a JSON Pointer path restricted to a single top-level key.

    Returns the decoded key string. Raises ValueError on invalid input.
    """
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    if not path.startswith("/"):
        raise ValueError(f"path must begin with '/': {path!r}")

    encoded = path[1:]

    # A raw '/' in the encoded portion means multiple segments (nested).
    if "/" in encoded:
        raise ValueError(f"nested paths are not supported: {path!r}")

    # Decode ~0 and ~1; reject any other ~ escape.
    decoded = []
    i = 0
    n = len(encoded)
    while i < n:
        ch = encoded[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError(f"invalid escape at end of path: {path!r}")
            esc = encoded[i + 1]
            if esc == "0":
                decoded.append("~")
            elif esc == "1":
                decoded.append("/")
            else:
                raise ValueError(
                    f"invalid escape '~{esc}' in path: {path!r}"
                )
            i += 2
        else:
            decoded.append(ch)
            i += 1

    return "".join(decoded)


def apply_patch(document, operations):
    """Apply a list of top-level JSON-object patch operations to *document*.

    Supported operations: add, replace, remove, test.
    Returns a new deep-copied dict; never mutates *document* or *operations*.
    """
    if not isinstance(document, dict):
        raise ValueError("document must be a JSON object (dict)")
    if not isinstance(operations, list):
        raise ValueError("operations must be a list")

    result = copy.deepcopy(document)

    for idx, op in enumerate(operations):
        if not isinstance(op, dict):
            raise ValueError(f"operation {idx} must be a dict")

        op_type = op.get("op")
        if op_type not in ("add", "replace", "remove", "test"):
            raise ValueError(
                f"operation {idx}: invalid op {op_type!r}; "
                f"expected 'add', 'replace', 'remove', or 'test'"
            )

        if "path" not in op:
            raise ValueError(f"operation {idx}: missing required 'path'")

        key = _parse_path(op["path"])

        # Value is optional for every op; default to None when absent.
        value = op["value"] if "value" in op else None

        if op_type == "add":
            result[key] = copy.deepcopy(value)

        elif op_type == "replace":
            if key not in result:
                raise ValueError(
                    f"operation {idx}: replace requires existing key {key!r}"
                )
            result[key] = copy.deepcopy(value)

        elif op_type == "remove":
            if key not in result:
                raise ValueError(
                    f"operation {idx}: remove requires existing key {key!r}"
                )
            del result[key]

        elif op_type == "test":
            if key not in result:
                raise ValueError(
                    f"operation {idx}: test requires existing key {key!r}"
                )
            if result[key] != value:
                raise ValueError(
                    f"operation {idx}: test failed for key {key!r} "
                    f"(expected {value!r}, got {result[key]!r})"
                )

    return result
